/**
 * Keep the critical application styles in the generated HTML.
 *
 * On hosts that serve an old HTML document while rotating hashed /assets files,
 * a stale stylesheet URL would otherwise leave the whole React UI unstyled.
 * Inline the CSS generated by Vite so the page is independent of stylesheet
 * asset URLs. The source CSS remains in src/styles and is still processed by Vite.
 *
 * This postbuild step runs for both Vercel and GitHub Pages.
 */
import { readFile, readdir, writeFile } from 'node:fs/promises'
import { join } from 'node:path'

const outputDirectory = 'dist'
const indexPath = join(outputDirectory, 'index.html')
const assetsDirectory = join(outputDirectory, 'assets')
const html = await readFile(indexPath, 'utf8')
const cssFiles = (await readdir(assetsDirectory)).filter(name => /^.+\.css$/.test(name)).sort()

if (!cssFiles.length) {
  throw new Error('No generated stylesheets found in dist/assets. Cannot publish an unstyled portal.')
}
if (!html.includes('</head>')) {
  throw new Error('Missing closing head tag in dist/index.html.')
}

const css = (await Promise.all(cssFiles.map(file => readFile(join(assetsDirectory, file), 'utf8'))))
  .join('\n')
  .replaceAll('</style', '<\\/style')
const inlineStyle = '<style data-portal-critical-css>\n' + css + '\n</style>'
const result = html.replace('</head>', '  ' + inlineStyle + '\n</head>')
await writeFile(indexPath, result, 'utf8')
console.log('Embedded ' + cssFiles.length + ' generated stylesheet(s) in dist/index.html.')
